from functools import reduce

def compose_left(functions):
    return lambda x: reduce(lambda f, g: f(g), reversed(functions), x)

def curry(func, *args, **kwargs):
    if not sigs.has_varargs(func) and not sigs.has_keywords(func):
        return func
    else:
        def curried(*more_args, **more_kwargs):
            if sigs.has_varargs(func) or sigs.has_keywords(func):
                return curried
            else:
                return func(*args, *more_args, **kwargs, **more_kwargs)
        return curried
